using System.Windows.Controls;using Crown___Sovereign.Data;namespace Crown___Sovereign.Views.UserControls.Gerencia.Supervision;public partial class MantenimientoResumenControl:UserControl{public MantenimientoResumenControl(){InitializeComponent();IncidentsGrid.ItemsSource=SampleData.Incidencias.Select(i=>new{Habitacion=SampleData.Habitaciones.First(r=>r.Id==i.Habitacion).Numero,i.Descripcion,i.Prioridad,i.Estado,i.BloqueaHabitacion}).ToList();}}
